Análise: escrevendo a palavra como sequência i₀, i₁, …, iₘ (última = ℓ), a nasalidade final é

A = Σ aᵢ − Σ_{i≠ℓ} bᵢ,

pois cada sílaba anexada subtrai a resistência da **anterior**. A condição de anexar i_t vira Σ_{s≤t} a ≥ Σ_{s<t} b, ou seja, Σ_{s≤t} d_s + b_{i_t} ≥ 0 com d = a−b. Escrevendo aᵢ = pᵢ + gᵢ (com pᵢ = max(0, aᵢ−bᵢ) e gᵢ = min(aᵢ,bᵢ)), tem‑se bᵢ = aᵢ − pᵢ, e o valor da palavra = Σ_{usadas} pᵢ + g_ℓ (a última sílaba "promove" ganho g_ℓ; zerar b de uma sílaba usada no meio também a promove em gᵢ).

Argumentos de troca mostram que na solução ótima toda sílaba do meio (exceto a última) tem a ≥ b (após zeragens) — e nesse caso **qualquer** ordem é válida, pois cada condição vira (soma de d's do prefixo ≥ 0) + b ≥ 0. Logo a resposta é:

**Σ max(0, aᵢ−bᵢ) + soma dos min(K+1, N) maiores valores de min(aᵢ,bᵢ)** (K+1 =  sílaba final promovida + K zeragens).

Verificado nos 4 exemplos (13, 12, 10, 10) e em força bruta manual em vários casos.

```c
#include <stdio.h>
#include <stdlib.h>

static int cmp_desc(const void *x, const void *y){
    long long a = *(const long long *)x;
    long long b = *(const long long *)y;
    if (a > b) return -1;
    if (a < b) return 1;
    return 0;
}

int main(void){
    int n;
    long long k;
    if (scanf("%d %lld", &n, &k) != 2) return 0;

    long long *a = malloc((size_t)n * sizeof(long long));
    long long *b = malloc((size_t)n * sizeof(long long));
    long long *g = malloc((size_t)n * sizeof(long long));
    if (!a || !b || !g) return 0;

    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    for (int i = 0; i < n; i++) scanf("%lld", &b[i]);

    long long sump = 0;
    for (int i = 0; i < n; i++){
        long long d = a[i] - b[i];
        if (d > 0) sump += d;
        g[i] = a[i] < b[i] ? a[i] : b[i];
    }

    qsort(g, (size_t)n, sizeof(long long), cmp_desc);

    long long t = k + 1;
    if (t > (long long)n) t = n;

    long long add = 0;
    for (long long i = 0; i < t; i++) add += g[i];

    printf("%lld\n", sump + add);

    free(a); free(b); free(g);
    return 0;
}
```

